233	function AddColumn($Column, $Table, $Type, $Null, $Default, $After) {
234		global $SQLFile;
235		if (DB_table_exists($Table)) {
236			$SQL = "desc " . $Table . " " . $Column;
237			$Result = DB_query($SQL);
238			if (isset($SQLFile) or DB_num_rows($Result) == 0) {
239				if ($Type == 'text') {
240					$SQL = "ALTER TABLE `" . $Table . "` ADD COLUMN `" . $Column . "` " . $Type . " " . $Null . " AFTER `" . $After . "`";
241				} else {
242					if (isset($Default) and $Default != '') {
243						if ($Default == 'CURRENT_TIMESTAMP') {
244							$SQL = "ALTER TABLE `" . $Table . "` ADD COLUMN `" . $Column . "` " . $Type . " " . $Null . " DEFAULT " . $Default . " AFTER `" . $After . "`";
245						} else {
246							$SQL = "ALTER TABLE `" . $Table . "` ADD COLUMN `" . $Column . "` " . $Type . " " . $Null . " DEFAULT '" . $Default . "' AFTER `" . $After . "`";
247						}
248					} else {
249						$SQL = "ALTER TABLE `" . $Table . "` ADD COLUMN `" . $Column . "` " . $Type . " " . $Null . " AFTER `" . $After . "`";
250					}
251				}
252				$Response = executeSQL($SQL);
253				if ($Response == 0) {
254					OutputResult(__('The column') . ' ' . $Column . ' ' . __('has been inserted'), 'success');
255				} else {
256					OutputResult(__('The column') . ' ' . $Column . ' ' . __('could not be inserted') . '<br />' . $SQL, 'error');
257				}
258			} else {
259				OutputResult(__('The column') . ' ' . $Column . ' ' . __('already exists'), 'info');
260			}
261		}
262	}
