			fclose($CompanyFileHandler);
			echo '<div class="error">' . __('Cannot write to the Companies.php file') . '</div>';
		}
		//close file
		fclose($CompanyFileHandler);

		$SQL = "UPDATE companies SET coyname='" . $_POST['CoyName'] . "',
