			prnMsg(__('Your account is currently on hold so this order cannot be accepted. Please contact us to arrange payment'), 'error');
		} else {
			prnMsg($CreditCheck['message'], 'error');
		}
	} elseif ($CreditCheck['result'] == 'hold') {
		$CreditHold = true;
		prnMsg($CreditCheck['message'], 'warn');
	} elseif ($CreditCheck['watch'] and $CustomerLogin != 1) {
		prnMsg(__('This customer is on credit watch. The order has been accepted and credit control can see it'), 'warn');
	}
}

